const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, HeadingLevel, BorderStyle, WidthType,
  ShadingType, PageBreak, LevelFormat, TabStopType, TabStopPosition, SimpleField
} = require('docx');
const fs = require('fs');

const GOLD = "C9A84C";
const NAVY = "1B2A4A";
const LIGHT_GOLD = "F9F3E3";
const LIGHT_NAVY = "EEF1F7";
const WHITE = "FFFFFF";
const DARK_GRAY = "333333";

const border = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorders = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" }
};

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 100 },
    children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color: GOLD })]
  });
}

function h3(text) {
  return new Paragraph({
    spacing: { before: 200, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: NAVY })]
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: DARK_GRAY, ...opts })]
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 50, after: 50 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: DARK_GRAY })]
  });
}

function divider(color = GOLD) {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color, space: 1 } },
    children: []
  });
}

function spacer() {
  return new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun("")] });
}

function sectionBanner(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: noBorders,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 240, right: 240 },
        width: { size: 9360, type: WidthType.DXA },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color: GOLD })]
        })]
      })]
    })]
  });
}

function highlightBox(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: noBorders,
        shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
        margins: { top: 140, bottom: 140, left: 240, right: 240 },
        width: { size: 9360, type: WidthType.DXA },
        children: [new Paragraph({
          children: [new TextRun({ text, font: "Arial", size: 22, color: NAVY, italics: true })]
        })]
      })]
    })]
  });
}

function twoColTable(rows, col1Width = 4200, col2Width = 5160) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [col1Width, col2Width],
    rows: rows.map(([left, right, isHeader]) =>
      new TableRow({
        children: [
          new TableCell({
            borders,
            shading: { fill: isHeader ? NAVY : WHITE, type: ShadingType.CLEAR },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            width: { size: col1Width, type: WidthType.DXA },
            children: [new Paragraph({
              children: [new TextRun({ text: left, font: "Arial", size: 20, bold: isHeader, color: isHeader ? GOLD : DARK_GRAY })]
            })]
          }),
          new TableCell({
            borders,
            shading: { fill: isHeader ? NAVY : LIGHT_GOLD, type: ShadingType.CLEAR },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            width: { size: col2Width, type: WidthType.DXA },
            children: [new Paragraph({
              children: [new TextRun({ text: right, font: "Arial", size: 20, bold: isHeader, color: isHeader ? GOLD : DARK_GRAY })]
            })]
          })
        ]
      })
    )
  });
}

function mathTable(rows) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [5400, 3960],
    rows: rows.map(([left, right, isHeader]) =>
      new TableRow({
        children: [
          new TableCell({
            borders,
            shading: { fill: isHeader ? NAVY : WHITE, type: ShadingType.CLEAR },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            width: { size: 5400, type: WidthType.DXA },
            children: [new Paragraph({
              children: [new TextRun({ text: left, font: "Arial", size: 20, bold: isHeader, color: isHeader ? GOLD : DARK_GRAY })]
            })]
          }),
          new TableCell({
            borders,
            shading: { fill: isHeader ? NAVY : LIGHT_NAVY, type: ShadingType.CLEAR },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            width: { size: 3960, type: WidthType.DXA },
            children: [new Paragraph({
              alignment: AlignmentType.RIGHT,
              children: [new TextRun({ text: right, font: "Arial", size: 20, bold: !isHeader, color: isHeader ? GOLD : NAVY })]
            })]
          })
        ]
      })
    )
  });
}

const doc = new Document({
  numbering: {
    config: [{
      reference: "bullets",
      levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 720, hanging: 360 } } } }]
    }]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 32, bold: true, font: "Arial", color: NAVY },
        paragraph: { spacing: { before: 400, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Arial", color: GOLD },
        paragraph: { spacing: { before: 280, after: 100 }, outlineLevel: 1 } }
    ]
  },
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 }, margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
          border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 1 } },
          children: [
            new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 18, bold: true, color: NAVY }),
            new TextRun({ text: "\tNickel & Dodge  |  Custom Growth Engine Strategy", font: "Arial", size: 16, color: GOLD })
          ]
        })]
      })
    },
    footers: {
      default: new Footer({
        children: [new Paragraph({
          tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
          border: { top: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 1 } },
          children: [
            new TextRun({ text: "Confidential  |  theluxoracollective.co", font: "Arial", size: 16, color: GOLD }),
            new TextRun({ text: "\tPage ", font: "Arial", size: 16, color: DARK_GRAY }),
            new SimpleField("PAGE")
          ]
        })]
      })
    },
    children: [

      // ── COVER ────────────────────────────────────────────────────────────
      spacer(), spacer(), spacer(),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 80 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 44, bold: true, color: NAVY })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 240 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 4 } },
        children: [new TextRun({ text: "Custom Growth Engine Strategy", font: "Arial", size: 28, color: GOLD })]
      }),
      spacer(),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 160, after: 80 },
        children: [new TextRun({ text: "Nickel & Dodge", font: "Arial", size: 40, bold: true, color: NAVY })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 240 },
        children: [new TextRun({ text: "Minot, North Dakota", font: "Arial", size: 26, color: DARK_GRAY })]
      }),
      spacer(),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 80, after: 80 },
        children: [new TextRun({ text: "5 Initiatives  \u00B7  Military Base Strategy  \u00B7  Retail Trust Model  \u00B7  90-Day Roadmap", font: "Arial", size: 20, color: GOLD, bold: true })]
      }),
      spacer(), spacer(),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 240, after: 80 },
        children: [new TextRun({ text: "Prepared by The Luxora Collective  \u00B7  Confidential", font: "Arial", size: 18, color: GOLD, italics: true })]
      }),
      new Paragraph({ children: [new PageBreak()] }),

      // ── SITUATION SNAPSHOT ───────────────────────────────────────────────
      sectionBanner("SITUATION SNAPSHOT"),
      spacer(),
      twoColTable([
        ["The Business", "Previous Agencies That Failed", true],
        ["Minot, ND: small, family-oriented military community", "Clinic Grower and Jump Forward: both focused on lead gen, ignored systems and retention", false],
        ["Packages offered, no membership program yet", "Neither identified the military base opportunity", false],
        ["2 new associate providers joining soon (90 new sellable hours)", "Neither touched the retail channel", false],
        ["Owner also opening a beautician school", "Both poured water into a leaking ship", false],
        ["Staff trained in trust-based retail education", "", false],
        ["Shopify page exists but underperforming  \u00B7  CRM: Forrestt", "", false],
      ]),
      spacer(),

      // ── THE REAL PROBLEM ─────────────────────────────────────────────────
      sectionBanner("THE REAL PROBLEM"),
      spacer(),
      body("Nickel & Dodge does not have a lead problem. They have four interconnected problems that no lead generation agency will ever fix."),
      spacer(),
      twoColTable([
        ["Problem", "What It Means", true],
        ["Capacity Without Systems", "90 new sellable hours arriving. Without a system to fill them, they are a cost center, not a revenue driver.", false],
        ["No Recurring Revenue Floor", "Packages without memberships means every month starts at zero.", false],
        ["Owner Is the Bottleneck", "Running a medspa and opening a beautician school with time already spread thin. Nothing scales if everything runs through the owner.", false],
        ["Untapped Revenue Sitting Idle", "A military base with 5,000+ personnel next door and a retail channel with trained staff. Both completely untouched.", false],
      ], 3200, 6160),
      spacer(),
      new Paragraph({ children: [new PageBreak()] }),

      // ── INITIATIVES OVERVIEW ─────────────────────────────────────────────
      sectionBanner("THE LUXORA GAME PLAN: 5 INITIATIVES"),
      spacer(),
      twoColTable([
        ["Initiative", "Priority", true],
        ["01  Reactivation Campaign", "Do This First: Fast Revenue, Zero Ad Spend", false],
        ["02  Military Base Marketing", "Highest Long-Term Potential: Nobody Has Done This", false],
        ["03  Membership Program Launch", "Recurring Revenue Floor: Compounding Monthly", false],
        ["04  Activate the 90 New Hours", "Critical: Must Happen Before Providers Arrive", false],
        ["05  Retail Trust Model", "Lifetime Value: The Hidden Asset Already Built", false],
      ]),
      spacer(),
      new Paragraph({ children: [new PageBreak()] }),

      // ── INITIATIVE 1 ─────────────────────────────────────────────────────
      sectionBanner("INITIATIVE 1: REACTIVATION CAMPAIGN"),
      spacer(),
      body("Do This First  \u00B7  Days 1\u201330  \u00B7  No ad spend required", { bold: true, color: GOLD }),
      spacer(),
      body("The fastest money in any medspa is sitting in the existing client list. Before spending a dollar on new acquisition, we go back to everyone who has visited and has not returned in 90+ days. In a small, relationship-driven community like Minot, a personal outreach feels genuine and converts."),
      spacer(),
      h3("What We Build"),
      bullet("Segmented reactivation list from Forrestt, sorted by last visit date and service type"),
      bullet("Personalized 3-touch sequence: text and email over two weeks"),
      bullet("Reactivation offer: not a discount, a reason to return (new provider preview, exclusive early access, referral incentive)"),
      bullet("Front desk script for converting reactivation calls to booked appointments"),
      spacer(),
      mathTable([
        ["Metric", "Projection", true],
        ["Industry reactivation recovery rate", "15\u201325% of dormant clients", false],
        ["20 reactivated clients at $350\u2013$600 avg", "$7,000\u2013$12,000 in 30 days", false],
      ]),
      spacer(),
      new Paragraph({ children: [new PageBreak()] }),

      // ── INITIATIVE 2 ─────────────────────────────────────────────────────
      sectionBanner("INITIATIVE 2: MILITARY BASE MARKETING"),
      spacer(),
      body("Highest Long-Term Potential  \u00B7  No Competitor Has Claimed This  \u00B7  Wide Open", { bold: true, color: GOLD }),
      spacer(),
      body("Minot Air Force Base has approximately 5,000 active duty personnel plus dependents. Clinic Grower never pitched this. Jump Forward never pitched this. No agency has. It is sitting there completely unclaimed."),
      spacer(),
      h3("Why This Community Is Different"),
      bullet("Networked: military spouses share everything. One great experience reaches an entire unit's spouse network"),
      bullet("Constantly arriving: families rotate on 2\u20133 year cycles, a steady stream of people actively looking for trusted local providers"),
      bullet("Fiercely loyal: once a military family trusts a business, they do not comparison shop"),
      bullet("Real disposable income: military pay plus housing allowance gives many families significant spending power"),
      spacer(),
      h3("The Channels That Actually Work"),
      bullet("Key Spouse Network: one relationship with a Key Spouse reaches dozens of families immediately"),
      bullet("Spouse Clubs + Family Resource Center: sponsoring or presenting at a base event positions Nickel & Dodge as a community partner"),
      bullet("Base Facebook Groups: one authentic post from a happy military client generates more bookings than any paid campaign"),
      bullet("Welcome Packet: getting into the base welcome packet means every new family meets the practice before finding anyone else"),
      bullet("Geofenced Meta Ads: $200\u2013$400/month, every impression goes to someone within a mile of Minot AFB"),
      spacer(),
      highlightBox("Welcome to Minot. We have been waiting for you. Here is what we have built for the base community, because you deserve a provider who takes care of you the way you take care of everyone else."),
      spacer(),
      bullet("Military Welcome Package: curated first-visit experience (consultation + treatment at an introductory investment). Not a discount. An introduction."),
      bullet("Military Membership Tier: priced and marketed explicitly as a benefit for those who serve"),
      bullet("The PCS Bridge: when families move, their skincare protocol travels with them through the Shopify store, keeping the relationship alive after PCS orders arrive"),
      spacer(),
      mathTable([
        ["Metric", "Projection", true],
        ["Realistic addressable audience on base", "~2,000 spouses + personnel", false],
        ["Conservative 5% conversion over 12 months", "100 new clients", false],
        ["Average annual client value", "$1,800\u2013$3,000", false],
        ["Annual revenue at 5% base penetration", "$180,000\u2013$300,000", false],
      ]),
      spacer(),
      new Paragraph({ children: [new PageBreak()] }),

      // ── INITIATIVE 3 ─────────────────────────────────────────────────────
      sectionBanner("INITIATIVE 3: LAUNCH THE MEMBERSHIP PROGRAM"),
      spacer(),
      body("Days 30\u201360  \u00B7  Guaranteed Recurring Revenue That Grows Every Month", { bold: true, color: GOLD }),
      spacer(),
      body("Packages create one-time revenue. Memberships create a guaranteed monthly floor that compounds. This is the highest-leverage financial move available right now."),
      spacer(),
      mathTable([
        ["Members", "Monthly Recurring Revenue", true],
        ["50 members at $150/month", "$7,500 guaranteed", false],
        ["100 members at $150/month", "$15,000 guaranteed", false],
        ["150 members at $150/month", "$22,500 before a new client walks in", false],
      ]),
      spacer(),
      h3("What We Build"),
      bullet("2 to 3 membership tiers designed for Minot market pricing: accessible, community-appropriate, meaningful revenue"),
      bullet("Military-specific tier that converts base clients to long-term recurring revenue"),
      bullet("Conversion strategy for existing package clients: they are already bought in"),
      bullet("Front desk membership pitch: simple, non-pushy, conversion-focused"),
      bullet("Forrestt CRM integration for automated billing and member management"),
      spacer(),
      new Paragraph({ children: [new PageBreak()] }),

      // ── INITIATIVE 4 ─────────────────────────────────────────────────────
      sectionBanner("INITIATIVE 4: ACTIVATE THE 90 NEW HOURS"),
      spacer(),
      body("Critical  \u00B7  Must Happen Before the New Providers Arrive", { bold: true, color: GOLD }),
      spacer(),
      body("Two new associate providers mean 90 additional sellable hours per week. If those hours sit empty they are a cost. If they are filled before the providers arrive they are profit from day one."),
      spacer(),
      h3("What We Build"),
      bullet("'Meet Our New Providers' campaign: a community announcement that feels like an invitation, not an ad"),
      bullet("Introductory rate packages for new provider bookings: limited availability, genuine urgency"),
      bullet("Online booking visibility so new provider hours are easy to find and book directly"),
      bullet("Cross-booking strategy: existing clients get first access"),
      bullet("Provider onboarding playbook: scripts, standards, and brand protocols from day one"),
      spacer(),
      highlightBox("'Be one of the first to experience our new providers at exclusive introductory rates. Limited spots available.' Scarcity plus community invitation equals full books from week one."),
      spacer(),
      new Paragraph({ children: [new PageBreak()] }),

      // ── INITIATIVE 5 ─────────────────────────────────────────────────────
      sectionBanner("INITIATIVE 5: RETAIL TRUST MODEL"),
      spacer(),
      body("The Hidden Asset  \u00B7  Already Built  \u00B7  $24,000\u2013$40,000 Annual Upside", { bold: true, color: GOLD }),
      spacer(),
      body("Nickel & Dodge already has something most medspas spend years trying to build: a staff that clients trust deeply enough to take advice from. The team's education-based approach is one of the most powerful retail assets in the business. It just needs a system behind it."),
